import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env_mapping=os.environ):
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            nested_keys = key[len(env_prefix):].split('__')
            current = config
            for k in nested_keys[:-1]:
                if k not in current:
                    current[k] = {}
                current = current[k]
            current[nested_keys[-1]] = _coerce(value)
    return config

def _coerce(value):
    if value.isdigit():
        return int(value)
    if value.lower() in ('true', 'yes', '1'):
        return True
    if value.lower() in ('false', 'no', '0'):
        return False
    return value

import pytest
from envcfg import load_config, ConfigError

def test_load_defaults():
    defaults = {'a': 1, 'b': 'two'}
    assert load_config(defaults) == {'a': 1, 'b': 'two'}

def test_load_toml():
    defaults = {'a': 1, 'b': 'two'}
    toml_content = b'a = 3\nb = "three"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    assert load_config(defaults, 'config.toml') == {'a': 3, 'b': 'three'}

def test_load_env():
    defaults = {'a': 1, 'b': 'two'}
    os.environ['APP__A'] = '4'
    os.environ['APP__B'] = 'four'
    assert load_config(defaults, env_prefix='APP__') == {'a': 4, 'b': 'four'}

def test_coerce_int():
    assert _coerce('5') == 5

def test_coerce_bool():
    assert _coerce('true') == True
    assert _coerce('false') == False

def test_coerce_string():
    assert _coerce('hello') == 'hello'

def test_missing_toml():
    defaults = {'a': 1, 'b': 'two'}
    assert load_config(defaults, 'missing.toml') == {'a': 1, 'b': 'two'}

def test_missing_env():
    defaults = {'a': 1, 'b': 'two'}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='MISSING__')

